void stress_metrics_set(
	stress_args_t *args,
	const char *description,
	const double value,
	const int mean_type)
{
	stress_stats_t *stats;
	stress_list_item_t *item;
	ssize_t idx;

	if (!args)
		return;
	stats = args->stats;
	if (!stats)
		return;
	item = stats->item;
	if (!item)
		return;

	idx = stress_metrics_find(item, description, mean_type);
	if (idx < 0)
		return;
	stats->metrics_values[idx] = value;
}

