344	static int stress_cacheline_rdrev64(
345		stress_args_t *args,
346		const int idx,
347		const bool parent,
348		const size_t l1_cacheline_size)
349	{
350		register int i;
351		volatile uint8_t *buffer = (volatile uint8_t *)g_shared->cacheline.buffer;
352		volatile uint8_t *data8 = buffer + idx;
353		const ssize_t cacheline_size = (ssize_t)g_shared->cacheline.size;
354		uintptr_t aligned_cacheline = (uintptr_t)buffer & ~(l1_cacheline_size - 1);
355	
356		(void)parent;
357		(void)l1_cacheline_size;
358	
359		for (i = 0; i < 1024; i++) {
360			register ssize_t j;
361			uint8_t val8;
362	
363			(*data8)++;
364			val8 = *data8;
365	
366			/* read cache line backwards */
367	PRAGMA_UNROLL
368			for (j = cacheline_size - 8; j >= 0; j -= 8) {
369				volatile const uint64_t *data64 = (volatile const uint64_t *)(aligned_cacheline + (size_t)j);
370	
371				(void)*data64;
372				stress_asm_mb();
373			}
374			if (UNLIKELY(val8 != *data8)) {
375				pr_fail("%s: rdrev64 method: cache line error in offset 0x%x, expected %2" PRIx8 ", got %2" PRIx8 "\n",
376					args->name, (unsigned int)idx, val8, *data8);
377				return EXIT_FAILURE;
378			}
379		}
380		return EXIT_SUCCESS;
381	}
