687	static int stress_cacheline_next_idx(void)
688	{
689		int ret;
690	
691		if (stress_lock_acquire(g_shared->cacheline.lock) < 0)
692			return -1;
693	
694		ret = g_shared->cacheline.index;
695		g_shared->cacheline.index++;
696	
697		if (stress_lock_release(g_shared->cacheline.lock) < 0)
698			return -1;
699	
700		return ret * 2;
701	}
