703	/*
704	 *  stress_cacheline()
705	 *	exercise a cacheline by multiple processes
706	 */
707	static int stress_cacheline(stress_args_t *args)
708	{
709		size_t l1_cacheline_size = (size_t)get_L1_line_size(args);
710		int idx;
711		int rc = EXIT_SUCCESS;
712		size_t cacheline_method = 0;
713		stress_cacheline_func func;
714		bool cacheline_affinity = false;
715		size_t n_pids;
716		size_t i;
717		stress_pid_t *s_pids = NULL;
718		stress_pid_t *s_pids_head = NULL;
719	
720		if (stress_signal_sigchld_handler(args) < 0)
721			return EXIT_NO_RESOURCE;
722	
723		if (!g_shared->cacheline.lock) {
724			pr_inf_skip("%s: failed to initialize cacheline lock, skipping stressor\n", args->name);
725			return EXIT_NO_RESOURCE;
726		}
727	
728		idx = stress_cacheline_next_idx();
729		if (idx < 0) {
730			pr_inf_skip("%s: failed to get cacheline idx, skipping stressor\n", args->name);
731			return EXIT_NO_RESOURCE;
732		}
733	
734		if (l1_cacheline_size > args->instances) {
735			n_pids = (l1_cacheline_size - args->instances) / args->instances;
736			if (((n_pids * args->instances) + args->instances) < l1_cacheline_size)
737				n_pids++;
738		} else {
739			n_pids = 0;
740		}
741	
742		if (stress_instance_zero(args))
743			pr_inf("%s: running %zu processes per stressor instance (%zu cacheline processes in total)\n",
744				args->name, (n_pids + 1), (n_pids + 1) * args->instances);
745	
746		if (n_pids > 1) {
747			s_pids = stress_sync_s_pids_mmap(n_pids);
748			if (s_pids == MAP_FAILED) {
749				pr_inf_skip("%s: failed to mmap %zu PIDs%s, skipping stressor\n",
750					args->name, n_pids, stress_memory_free_get());
751				return EXIT_NO_RESOURCE;
752			}
753		}
754	
755		(void)stress_setting_get("cacheline-affinity", &cacheline_affinity);
756		(void)stress_setting_get("cacheline-method", &cacheline_method);
757	
758		if (stress_instance_zero(args)) {
759			pr_dbg("%s: using method '%s'\n", args->name, cacheline_methods[cacheline_method].name);
760			pr_dbg("%s: L1 cache line size %zu bytes\n", args->name, l1_cacheline_size);
761		}
762	
763		func = cacheline_methods[cacheline_method].func;
764	
765		if (s_pids) {
766			for (i = 0; i < n_pids; i++) {
767				int child_idx;
768	
769				stress_sync_start_init(&s_pids[i]);
770	
771				child_idx = stress_cacheline_next_idx();
772				if (child_idx < 0) {
773					pr_inf_skip("%s: failed to get cacheline idx, skipping stressor\n", args->name);
774					rc = EXIT_NO_RESOURCE;
775					goto finish;
776				}
777				s_pids[i].pid = stress_retry_fork(args, 0);
778				if (s_pids[i].pid < 0) {
779					if (UNLIKELY(!stress_continue(args)))
780						goto finish;
781					pr_err("%s: fork failed, errno=%d: (%s)\n",
782						args->name, errno, strerror(errno));
783					goto finish;
784				} else if (s_pids[i].pid == 0) {
785					s_pids[i].pid = getpid();
786	
787					stress_proc_state_set(args->name, STRESS_STATE_SYNC_WAIT);
788					stress_sync_start_wait_s_pid(&s_pids[i]);
789					stress_proc_state_set(args->name, STRESS_STATE_RUN);
790					stress_make_it_fail_set();
791					stress_parent_died_alarm();
792					rc = stress_cacheline_child(args, child_idx, false, l1_cacheline_size, func, cacheline_affinity);
793					_exit(rc);
794				} else {
795					stress_sync_start_s_pid_list_add(&s_pids_head, &s_pids[i]);
796				}
797			}
798		}
799		stress_proc_state_set(args->name, STRESS_STATE_SYNC_WAIT);
800		stress_sync_start_wait(args);
801		if (s_pids)
802			stress_sync_start_cont_list(s_pids_head);
803		stress_proc_state_set(args->name, STRESS_STATE_RUN);
804	
805		stress_cacheline_child(args, idx, true, l1_cacheline_size, func, cacheline_affinity);
806	finish:
807		stress_proc_state_set(args->name, STRESS_STATE_DEINIT);
808	
809		if (s_pids && (n_pids > 1)) {
810			stress_kill_and_wait_many(args, s_pids, n_pids, SIGALRM, true);
811			(void)stress_sync_s_pids_munmap(s_pids, n_pids);
812		}
813	
814		return rc;
815	}
