/*
 *  stress_cacheline_rand_payload()
 *	word-granularity SDC-directed mutation (P6): each process owns
 *	one aligned 64-bit word of the shared buffer (word index from
 *	the same lock-protected counter as the byte idx, scaled by 8),
 *	fills it from a bitgen stream, then reads it back through the
 *	same cacheline-contention barrier pattern as the other methods
 *	and verifies against a same-seed replay of the stream.  This
 *	gives the cache-line stress the SDC-directed operand shapes
 *	(bandwalk windows, boundary dictionary) that the existing
 *	byte-state-machine methods cannot carry.  The owned byte of
 *	the process keeps its classic inc semantics via the low byte
 *	of the filled word, so the per-process cacheline ownership
 *	layout is preserved.
 */
static int stress_cacheline_rand_payload(
	stress_args_t *args,
	const int idx,
	const bool parent,
	const size_t l1_cacheline_size)
{
	register int i;
	volatile uint8_t *buffer = (volatile uint8_t *)g_shared->cacheline.buffer;
	const size_t size = g_shared->cacheline.size;
	const int word_off = (idx * 8) & ~(int)7;	/* own word, 8-aligned */
	volatile uint64_t *data64 =
		(volatile uint64_t *)(buffer + word_off);
	stress_bitgen_t bg, bg_verify;
	uint8_t tag8;

	(void)parent;
	(void)l1_cacheline_size;

	/* word must be inside the shared buffer */
	if ((size_t)(word_off + 8) > size) {
		pr_fail("%s: rand-payload method: word offset %d outside "
			"shared cacheline buffer\n", args->name, word_off);
		return EXIT_FAILURE;
	}

	tag8 = (uint8_t)idx;	/* ownership tag stays deterministic */

	stress_bitgen_init(&bg);
	(void)shim_memcpy(&bg_verify, &bg, sizeof(bg_verify));

